//! Calendar resource pack: digest verification, coverage, completion semantics and
//! cross-check against the Python-generated reference schedules.
//!
//! The pack under `stock-data/assets/calendars` is generated by
//! `tools/refactor/build_calendars.py` from the pinned `exchange_calendars` build.
//! The fixture schedules in `tests/fixtures/calendar/` were produced by the legacy
//! Python path from the same library, so a window slice of the pack must equal the
//! fixture session list byte for byte.
//!
//! A-CAL-01: the pack is schema 2.0 with sourced completion semantics. The continuous
//! `close_at` values are unchanged; the additional `auction_end_at` / `complete_at`
//! fields are the resolution boundary. A schema-1.0 pack stays readable for
//! diagnostics but can never be `library_verified` evidence.

use std::path::{Path, PathBuf};

use chrono::Datelike;
use sd_core::calendar::CalendarResource;
use sd_core::data_checks::{check_market, CheckOptions};
use sd_core::interfaces::CalendarProvider;
use sd_storage::calendar_resource::CalendarPack;
use serde_json::Value;
use sha2::{Digest, Sha256};

fn workspace_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn fixtures() -> PathBuf {
    workspace_root().join("tests/fixtures")
}

fn skill_root() -> PathBuf {
    workspace_root().join("../..")
}

fn pack() -> CalendarPack {
    CalendarPack::load_dir(&skill_root().join("assets/calendars")).expect("calendar pack loads")
}

fn scratch(label: &str) -> PathBuf {
    let directory =
        std::env::temp_dir().join(format!("sd-calendar-{label}-{}", std::process::id()));
    if directory.exists() {
        std::fs::remove_dir_all(&directory).expect("clean scratch");
    }
    std::fs::create_dir_all(&directory).expect("scratch");
    directory
}

fn copy_pack(destination: &Path) -> PathBuf {
    let source = skill_root().join("assets/calendars");
    std::fs::create_dir_all(destination).expect("pack dir");
    for name in ["manifest.json", "US.sessions.json", "HK.sessions.json"] {
        std::fs::copy(source.join(name), destination.join(name)).expect("copy");
    }
    destination.to_path_buf()
}

/// Rewrite a resource body and keep the manifest digest consistent, so a test can
/// isolate semantic validation from the digest check.
fn write_body_and_manifest(pack_dir: &Path, market: &str, body: &Value) {
    let file = format!("{market}.sessions.json");
    let canonical = serde_json::to_string(body).expect("canonical json");
    std::fs::write(pack_dir.join(&file), format!("{canonical}\n")).expect("write body");
    let digest = {
        let mut hasher = Sha256::new();
        hasher.update(canonical.as_bytes());
        format!("{:x}", hasher.finalize())
    };
    let mut manifest: Value = serde_json::from_str(
        &std::fs::read_to_string(pack_dir.join("manifest.json")).expect("manifest"),
    )
    .expect("manifest json");
    for entry in manifest["markets"].as_array_mut().expect("markets") {
        if entry["market"] == market {
            entry["sha256"] = Value::String(digest.clone());
            entry["bytes"] = Value::from(canonical.len() + 1);
        }
    }
    std::fs::write(
        pack_dir.join("manifest.json"),
        serde_json::to_string_pretty(&manifest).expect("manifest json") + "\n",
    )
    .expect("write manifest");
}

#[test]
fn pack_loads_both_markets_with_verified_digests_and_anchor() {
    let pack = pack();
    assert_eq!(pack.markets(), vec!["HK", "US"]);
    assert_eq!(pack.schema(), "2.0");
    assert_eq!(pack.completion_rule_version(), Some("cas_latest_end_v1"));
    assert!(pack.completion_verified());
    for market in ["US", "HK"] {
        let resource = pack.resource(market).expect("market resource");
        assert!(
            resource.anchors_phase(),
            "{market} must cover the 2000-01-03 phase anchor"
        );
        assert_eq!(resource.coverage_start, "2000-01-03");
        assert_eq!(resource.coverage_end, "2030-12-31");
        assert_eq!(&resource.source[..19], "exchange_calendars ");
        assert!(
            resource.completion_is_verified(),
            "{market} must carry verified completion semantics"
        );
        let provenance = resource
            .completion
            .provenance()
            .expect("schema-2.0 provenance");
        assert_eq!(provenance.rule_version, "cas_latest_end_v1");
        assert!(provenance.covers_market(market));
        assert!(!provenance.sources.is_empty(), "official sources required");
        assert!(
            provenance
                .sources
                .iter()
                .any(|source| source.url.starts_with("https://")),
            "sources must be http(s) URLs"
        );
    }
    // A decision near the end of the range still resolves a five-session target.
    let us = pack.resource("US").expect("US");
    let asof = chrono::DateTime::parse_from_rfc3339("2030-12-20T22:00:00Z")
        .unwrap()
        .with_timezone(&chrono::Utc);
    let decision = us
        .decision_session(asof)
        .expect("decision before coverage end");
    let target = us
        .target_session(decision, 5)
        .expect("five sessions inside the covered range");
    assert!(target.to_string().as_str() > decision.to_string().as_str());
    assert!(target.to_string() <= us.coverage_end);
}

#[test]
fn pack_completion_boundaries_match_the_sourced_rules() {
    let pack = pack();
    let hk = pack.resource("HK").expect("HK");
    let by_date = |day: &str| {
        hk.sessions
            .iter()
            .find(|session| session.date == day)
            .unwrap_or_else(|| panic!("HK session {day}"))
    };
    // CAS regime: continuous close 08:00Z, official latest auction end 08:10Z.
    let normal = by_date("2026-10-30");
    assert_eq!(normal.close_at, "2026-10-30T08:00:00Z");
    assert_eq!(
        normal.auction_end_at.as_deref(),
        Some("2026-10-30T08:10:00Z")
    );
    assert_eq!(normal.complete_at.as_deref(), Some("2026-10-30T08:10:00Z"));
    // Half day: continuous close 04:00Z, official latest auction end 04:10Z.
    let half = by_date("2026-12-24");
    assert_eq!(half.close_at, "2026-12-24T04:00:00Z");
    assert_eq!(half.complete_at.as_deref(), Some("2026-12-24T04:10:00Z"));
    // Historical closing-auction window: completion explicitly unverified.
    let unverified = by_date("2008-05-26");
    assert_eq!(unverified.complete_at, None);
    assert_eq!(unverified.auction_end_at, None);
    // Pre-CAS: no auction, completion equals the continuous close (no blanket offset).
    let pre_cas = by_date("2008-05-23");
    assert_eq!(pre_cas.complete_at.as_deref(), Some("2008-05-23T08:00:00Z"));
    assert_eq!(pre_cas.auction_end_at, None);
    let suspended = by_date("2009-03-23");
    assert_eq!(
        suspended.complete_at.as_deref(),
        Some("2009-03-23T08:00:00Z")
    );
    // US: no CAS-style extension, early close folded into the continuous close.
    let us = pack.resource("US").expect("US");
    for session in &us.sessions {
        assert_eq!(
            session.complete_at.as_deref(),
            Some(session.close_at.as_str()),
            "US {} completion must equal the continuous close",
            session.date
        );
    }
    let early = us
        .sessions
        .iter()
        .find(|session| session.date == "2026-11-27")
        .expect("US early close");
    assert_eq!(early.close_at, "2026-11-27T18:00:00Z");
    // HK sessions in the unverified historical window are skipped for resolution.
    let in_window = chrono::DateTime::parse_from_rfc3339("2008-05-27T00:00:00Z")
        .unwrap()
        .with_timezone(&chrono::Utc);
    assert_eq!(
        hk.decision_session(in_window)
            .map(|date| date.to_string())
            .as_deref(),
        Some("2008-05-23"),
        "the resolver must fall back to an earlier confirmed session"
    );
}

#[test]
fn pack_slices_match_the_python_reference_schedules() {
    let pack = pack();
    let fixture_root = fixtures().join("calendar");
    let mut compared = 0usize;
    let mut directories: Vec<PathBuf> = std::fs::read_dir(&fixture_root)
        .expect("calendar fixtures")
        .filter_map(Result::ok)
        .map(|entry| entry.path())
        .filter(|path| {
            path.is_dir() && !path.file_name().unwrap().to_string_lossy().starts_with('_')
        })
        .collect();
    directories.sort();
    for directory in directories {
        let name = directory
            .file_name()
            .unwrap()
            .to_string_lossy()
            .into_owned();
        let text = std::fs::read_to_string(directory.join("sessions.json")).expect("fixture");
        let fixture: Value = serde_json::from_str(&text).expect("fixture json");
        let market = if fixture["calendar"] == "XHKG" {
            "HK"
        } else {
            "US"
        };
        let resource: &CalendarResource = pack.resource(market).expect("market");
        let start = fixture["requested_range"]["start"].as_str().expect("start");
        let end = fixture["requested_range"]["end"].as_str().expect("end");
        let expected: Vec<(String, String)> = fixture["sessions"]
            .as_array()
            .expect("sessions")
            .iter()
            .map(|row| {
                (
                    row["date"].as_str().unwrap().to_string(),
                    row["close_at"].as_str().unwrap().to_string(),
                )
            })
            .collect();
        let actual: Vec<(String, String)> = resource
            .sessions_in_window(
                // `sessions_in_window` is left-open; shift the start one day back so the
                // inclusive fixture range matches.
                &previous_day(start),
                end,
            )
            .into_iter()
            .map(|session| (session.date.clone(), session.close_at.clone()))
            .collect();
        assert_eq!(
            actual, expected,
            "pack slice differs from the Python reference for {name}"
        );
        compared += 1;
    }
    assert_eq!(compared, 9, "all calendar fixtures must be compared");
}

fn previous_day(date: &str) -> String {
    use chrono::NaiveDate;
    let parsed = NaiveDate::parse_from_str(date, "%Y-%m-%d").expect("date");
    (parsed - chrono::Duration::days(1)).to_string()
}

#[test]
fn tampered_resource_is_rejected_before_use() {
    let source = skill_root().join("assets/calendars");
    let scratch = std::env::temp_dir().join(format!("sd-calendar-tamper-{}", std::process::id()));
    if scratch.exists() {
        std::fs::remove_dir_all(&scratch).expect("clean scratch");
    }
    std::fs::create_dir_all(&scratch).expect("scratch");
    for name in ["manifest.json", "US.sessions.json", "HK.sessions.json"] {
        std::fs::copy(source.join(name), scratch.join(name)).expect("copy");
    }
    // Flip one byte of the US resource body: the digest must catch it.
    let path = scratch.join("US.sessions.json");
    let mut bytes = std::fs::read(&path).expect("read");
    let position = bytes.len() / 2;
    bytes[position] = if bytes[position] == b'0' { b'1' } else { b'0' };
    std::fs::write(&path, &bytes).expect("write");
    let error = CalendarPack::load_dir(&scratch).expect_err("tampered pack must be rejected");
    assert!(
        error.message().contains("failed its digest check"),
        "unexpected error: {}",
        error.message()
    );
    let _ = std::fs::remove_dir_all(&scratch);
}

#[test]
fn coverage_helper_matches_provider_trait() {
    let pack = pack();
    let us = pack.resource("US").expect("US");
    // 2026 window: the resource must cover it, and the provider helper agrees.
    assert!(us.covers("2025-10-24", "2026-10-23"));
    assert!(CalendarProvider::covers(
        &pack,
        "US",
        "2025-10-24",
        "2026-10-23"
    ));
    assert!(!CalendarProvider::covers(
        &pack,
        "US",
        "1999-01-01",
        "2000-01-03"
    ));
    let sessions = CalendarProvider::sessions_in_window(&pack, "US", "2025-10-23", "2025-10-27");
    assert_eq!(
        sessions.len(),
        2,
        "2025-10-24 (Friday) and 2025-10-27 (Monday)"
    );
}

