#[test]
fn auto_resolution_finds_the_mounted_skill_pack() {
    // Development fallback walks up from cwd/executable; with the workspace inside the
    // Skill it must locate the real assets and load the verified pack.
    let root = sd_storage::calendar_resource::resolve_skill_root().expect("skill root");
    assert!(root.join("assets/calendars/manifest.json").is_file());
    let pack = sd_storage::calendar_resource::load_pack(None).expect("pack");
    assert!(pack.is_some());
}

/// A-CAL-01 invariant: loading the frozen legacy snapshots must reproduce the
/// Python-generated manifests byte-for-byte even with the schema-2.0 pack installed.
/// The completion evidence is gated on markets that need it (`market_has_auction_extension`),
/// so a US legacy snapshot gains no new evidence keys, warnings or reason codes.
#[test]
fn frozen_legacy_snapshots_stay_byte_identical_with_the_new_pack() {
    let fixtures_root = workspace_root().join("tests/fixtures");
    for case in ["complete-window", "missing-calendar"] {
        let loaded =
            sd_storage::snapshot::load_snapshot(&fixtures_root.join("snapshot").join(case))
                .expect("frozen snapshot loads");
        let expected_path = fixtures_root
            .join("load")
            .join(case)
            .join("expected-manifest.json");
        let expected: Value =
            serde_json::from_str(&std::fs::read_to_string(&expected_path).expect("expected"))
                .expect("expected json");
        assert_eq!(
            loaded.manifest, expected,
            "frozen load-time manifest differs for {case}"
        );
        let evidence = &loaded.manifest["data_validation"]["resolved_calendar_evidence"];
        if !evidence.is_null() {
            assert!(
                evidence.get("completion").is_none(),
                "{case}: US legacy evidence must not gain completion provenance"
            );
            assert!(
                evidence["sessions"]
                    .as_array()
                    .expect("sessions")
                    .iter()
                    .all(|row| row.get("complete_at").is_none()),
                "{case}: US legacy evidence must not gain per-session completion fields"
            );
        }
        // The pack is present and schema 2.0, but it does not rewrite frozen evidence.
        let pack = pack();
        assert_eq!(pack.schema(), "2.0");
    }
}
